def encoded(value): return (json.dumps(value,ensure_ascii=False,indent=2,sort_keys=True,allow_nan=False)+'\n').encode()
def digest(value): return hashlib.sha256(encoded(value)).hexdigest()

def main():
    p=argparse.ArgumentParser();p.add_argument('--repo',type=pathlib.Path,required=True);p.add_argument('--cases',type=pathlib.Path,required=True);p.add_argument('--packages',type=pathlib.Path,required=True);a=p.parse_args()
    root=a.repo.resolve(); out=root/BASE/'x1';out.mkdir(parents=True,exist_ok=True)
    def write(name,value):
        path=out/name
        if path.exists(): raise RuntimeError('exclusive planning artifact already exists: '+name)
        path.write_bytes(encoded(value) if not isinstance(value,str) else value.encode())
    cases=runpy.run_path(str(a.cases))['CASES'];by_op={r[0]:r for r in OPS}
    source_rows=json.loads(subprocess.check_output(['git','-C',str(root),'show',SOURCE+':docs/sable-rook/v687-v3/x1/new-proposals.json']))['proposals']
    proposals=[]
    for i,c in enumerate(cases,1):
        row=dict(c);ident=f'TH6874-N{i:03d}';op=by_op[c['operation']]
        row.update(id=ident,planning_only=True,pillar=op[2],practice=op[3],approval_class='safe_now',execution_lane='x2_owner_local_synthetic_only',inherited_execution_credit=0,semantic_distinction=op[5]+' Concrete requirement: '+c['title']+'.',hypothesis='The implementation will return the complete independently declared result for: '+c['title']+'.',null_or_failure_condition='Any type-sensitive complete-output mismatch, mutation accepted by the frozen oracle, input mutation, or out-of-scope evidence promotion.',concrete_artifacts=[BASE+'/x2/contract-results.json',BASE+'/x2/mutation-results.json'],falsifier_or_acceptance_gate='Type-sensitive complete-output equality; five explicit changed-result submissions must each fail the oracle; the original input must remain unchanged.',rollback_or_recovery='Retain the original definition and failed witness; add a correction with its own identifier. Never edit the x1 freeze or silently replace the expected result.',protected_gates=GATES,source_refs=['json-schema-2020-12','rfc6902','rfc6901','python-library-docs'],nearest_source_operation=op[4],novelty_scope='Distinct authored behavioral contract relative to the selected immediate-source corpus; no claim of global mathematical or software novelty.')
        row['mutations']=[dict(mutation_id=ident+'-M'+str(j),kind=kind,expected='REJECT',original_success_credit=0) for j,kind in enumerate(['remove_decision','unexpected_authority_field','type_flip_result','source_preservation_false','external_credit_true'],1)]
        proposals.append(row)
    assert len(proposals)==200 and len({digest((r['operation'],r['input'])) for r in proposals})==200
    write('new-proposals.json',dict(schema='ghc.family.teryn-proposals.v1',planning_only=True,proposals=proposals))
    write('inherited-review.json',dict(schema='ghc.family.inherited-review.v1',source=SOURCE,reviewed=200,new_owner_novelty_credit=0,new_owner_execution_credit=0,rows=[dict(source_id=r['id'],operation=r['operation'],title=r['title'],input=r['input'],expected_output=r['expected_output'],source_fingerprint=digest(r),new_owner_credit=0,review='Retained source evidence. A successful finite fixture does not establish universal correctness; nominal input variants do not automatically multiply semantic novelty.') for r in source_rows]))
    write('novelty-review.json',dict(schema='ghc.family.novelty-review.v1',source=SOURCE,selected_source_rows=200,new_authored_contracts=200,new_operation_families=10,global_novelty_claim=False,semantics_review=[dict(id=r['id'],neighbor=r['nearest_source_operation'],distinction=r['semantic_distinction'],falsifier=r['null_or_failure_condition'],input_fingerprint=digest(r['input']),frozen_output_fingerprint=digest(r['expected_output'])) for r in proposals]))
    write('identity.json',dict(owner='Teryn Halewick',phase='v687-v4',role='evidence continuity and migration reviewer',hope='Make each change easier to inspect without overstating what it proves.',pronouns='they/them',identity_boundary=BOUNDARY,priority_pillar='THOS Body',practices=sorted({r[3] for r in OPS}),next_practice='bounded migration rollback reviewer',registry_collision_check=dict(active_limit=50,archived_limit=50,exact_name_matches=0,archived_next_cursor=None,scope='Bounded native registry metadata; no transcript publication.')))
    write('source-verification.json',dict(source=SOURCE,source_branch='codex/GHC-Family/sable-rook-v687-v3-full-tools',baton_sha256='05470bc82a6362d87df33b6309a8a35b483324624b4c4564710263a4534c9069',baton_bytes=321794,baton_lines=3474,baton_words=36546,baton_read_through_eof=True,readout='All unique nonempty lines read; duplicate paragraphs matched exactly; truncated windows recovered before accepting EOF.',source_clean=True,source_divergence=[0,0],source_four_way_equal=True,source_phase_commits=3,source_merges=0,source_manifest_bindings=444,source_manifest_mismatches=0,canonical_receipt_sha256='7082c8e72b435dfa2d46b2f6f5e9296c0808701917f501f11bc8cad0490592aa',canonical_invocations=1,canonical_successes=1,canonical_replays=0,canonical_rerun_by_teryn=False,overlay_sha256='f9b99a035dfcd8be05d7b624f388c0493b4459e3648800a861672f7ebd3f085a',inherited_sealed_counts=dict(negatives=77893,methods=93045,failed_witnesses=48741,passing_witnesses=77040,open_gaps=674,exact_gates=659,proposals=14430),inherited_overlay_counts=dict(negatives=77896,methods=93048,failed_witnesses=48744,passing_witnesses=77043,open_gaps=674,exact_gates=659,proposals=14430)))
    write('package-plan.json',json.loads(a.packages.read_bytes()))
    write('skill-runner-plan.json',dict(planning_only=True,skills=[dict(name='ghc-family-'+r[1],operation=r[0],purpose=r[5],built=False) for r in OPS],runners=[dict(name='ghc_family_teryn_halewick_v687_v4_'+r[0]+'.py',operation=r[0],built=False) for r in OPS],global_promotions=dict(skills=10,shared_runners=5,dependency_files=1,collision_check_required=True,byte_parity_required=True)))
    safe=[dict(id=f'TH6874-S{i:03d}',proposal=r['id'],procedure='execute_frozen_contract',expected_execution_disposition='completed') for i,r in enumerate(proposals,1)]
    safe += [dict(id=f'TH6874-S{i+201:03d}',proposal=r['id'],procedure='verify_input_preservation',expected_execution_disposition='completed') for i,r in enumerate(proposals[:100])]
    cand=[dict(id=f'TH6874-C{i:03d}',proposal=r['id'],procedure='review_exact_result_falsifier',mutation=r['id']+'-M5',expected_execution_disposition='completed') for i,r in enumerate(proposals,1)]
    cand += [dict(id=f'TH6874-C{i+201:03d}',proposals=[proposals[2*i]['id'],proposals[2*i+1]['id']],procedure='review_two_case_dependency_bundle',expected_execution_disposition='completed') for i in range(50)]
    cfr=[]
