            cfr.append(dict(id=f'TH6874-{prefix}-{i+1:03d}',proposal=prop['id'],procedure=procedure,expected_execution_disposition='completed',scope='Additive task-card editing. This editorial operation does not create another proposal or independent scientific witness.'))
